package com.vanigam.clothing;

import org.json.*;
import java.util.*;
import java.math.*;
import java.text.SimpleDateFormat;
import java.security.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

/** All monetary values are integer paise; all sale/stock/points changes commit together. */
public final class Core {
 public static JSONObject obj(Object... kv)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<kv.length;i+=2)o.put((String)kv[i],kv[i+1]);return o;}
 public static String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 public static String now(){return new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(new Date());}
 public static JSONObject seed()throws Exception{return obj("schema",1,"version",0,"nextBill",1,"settings",obj("name","Vanigam Clothing","address","","phone","","gstin","","footer","Thank you for shopping with us!","logo","","earnSpend",10000,"pointValue",100,"minimumPoints",100,"loyalty",true,"taxRate",0),"users",new JSONArray(),"products",new JSONArray(),"bills",new JSONArray(),"customers",new JSONArray(),"movements",new JSONArray(),"points",new JSONArray(),"openings",new JSONArray(),"expenses",new JSONArray(),"audit",new JSONArray());}
 public static long money(String s)throws Exception{try{BigDecimal n=new BigDecimal(s.trim());if(n.signum()<0||n.scale()>2||n.compareTo(new BigDecimal("10000000"))>0)throw new Exception();return n.movePointRight(2).longValueExact();}catch(Exception e){throw new Exception("Enter a valid amount with at most 2 decimal places.");}}
 public static long bounded(JSONObject a,String key,long max)throws Exception{long n=a.getLong(key);if(n<0||n>max||a.getDouble(key)!=n)throw new Exception("Invalid "+key);return n;}
 public static String text(JSONObject a,String key,int max,boolean required)throws Exception{String t=a.optString(key,"").trim();if(t.length()>max||(required&&t.isEmpty()))throw new Exception("Check "+key+" (maximum "+max+" characters)");return t;}
 public static String id(){return UUID.randomUUID().toString();}
 public static JSONObject find(JSONArray arr,String id)throws Exception{for(int i=0;i<arr.length();i++)if(arr.getJSONObject(i).optString("id").equals(id))return arr.getJSONObject(i);throw new Exception("Record not found. Refresh and try again.");}
 public static JSONObject user(JSONObject s,String uid)throws Exception{JSONObject u=find(s.getJSONArray("users"),uid);if(!u.getBoolean("active"))throw new Exception("User disabled.");return u;}
 static void admin(JSONObject u)throws Exception{if(!u.optBoolean("admin"))throw new Exception("Only the administrator can change this.");}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(Locale.US,"%02x",x));return s.toString();}
 static String hash(String pin,String salt)throws Exception{return hex(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(new PBEKeySpec(pin.toCharArray(),salt.getBytes("UTF-8"),60000,256)).getEncoded());}
 public static String login(JSONObject s,String pin)throws Exception{if(!pin.matches("[0-9]{4}"))throw new Exception("Enter your 4-digit PIN.");for(int i=0;i<s.getJSONArray("users").length();i++){JSONObject u=s.getJSONArray("users").getJSONObject(i);if(u.optBoolean("active")&&MessageDigest.isEqual(hash(pin,u.getString("salt")).getBytes("UTF-8"),u.getString("hash").getBytes("UTF-8")))return u.getString("id");}throw new Exception("Incorrect PIN.");}
 static JSONObject createUser(JSONObject s,JSONObject a)throws Exception{String name=text(a,"name",40,true),pin=a.getString("pin");if(!pin.matches("[0-9]{4}"))throw new Exception("PIN must contain exactly 4 digits.");JSONArray us=s.getJSONArray("users");for(int i=0;i<us.length();i++){JSONObject u=us.getJSONObject(i);if(u.getString("name").equalsIgnoreCase(name))throw new Exception("User name already exists.");if(hash(pin,u.getString("salt")).equals(u.getString("hash")))throw new Exception("This PIN is already assigned. Choose another PIN.");}byte[] salt=new byte[24];new SecureRandom().nextBytes(salt);String str=hex(salt);JSONObject u=obj("id",id(),"name",name,"admin",us.length()==0||a.optBoolean("admin"),"active",true,"salt",str,"hash",hash(pin,str));us.put(u);return u;}
 static void audit(JSONObject s,String uid,String action)throws Exception{s.getJSONArray("audit").put(obj("time",now(),"user",uid,"action",action));}
 static String mobile(String m)throws Exception{m=m.replace(" ","").replace("-","").trim();if(m.startsWith("+91"))m=m.substring(3);if(!m.isEmpty()&&!m.matches("[0-9]{10}"))throw new Exception("Enter a 10-digit customer mobile.");return m;}
 static JSONObject customer(JSONObject s,String phone,boolean create)throws Exception{for(int i=0;i<s.getJSONArray("customers").length();i++){JSONObject c=s.getJSONArray("customers").getJSONObject(i);if(c.getString("mobile").equals(phone))return c;}if(!create||phone.isEmpty())return null;JSONObject c=obj("id",id(),"mobile",phone,"name","","points",0);s.getJSONArray("customers").put(c);return c;}
 public static JSONObject quote(JSONObject s,JSONObject a)throws Exception{
  JSONArray requested=a.getJSONArray("lines"),lines=new JSONArray();if(requested.length()==0||requested.length()>200)throw new Exception("Add 1–200 products.");Set<String> seen=new HashSet<>();long subtotal=0,cost=0;
  for(int i=0;i<requested.length();i++){JSONObject r=requested.getJSONObject(i),p=find(s.getJSONArray("products"),r.getString("id"));if(!seen.add(p.getString("id")))throw new Exception("Duplicate product line.");long q=bounded(r,"qty",100000);if(q==0||q>p.getLong("stock")||!p.getBoolean("active"))throw new Exception("Not enough stock for "+p.getString("name"));long amount=Math.multiplyExact(p.getLong("price"),q);subtotal=Math.addExact(subtotal,amount);cost=Math.addExact(cost,Math.multiplyExact(p.getLong("cost"),q));lines.put(obj("id",p.getString("id"),"sku",p.getString("sku"),"name",p.getString("name"),"size",p.getString("size"),"colour",p.getString("colour"),"qty",q,"price",p.getLong("price"),"cost",p.getLong("cost"),"amount",amount));}
  if(subtotal>1000000000L)throw new Exception("Bill is too large.");long discount=bounded(a,"discount",subtotal),redeem=bounded(a,"redeem",100000000);JSONObject settings=s.getJSONObject("settings");String phone=mobile(a.optString("mobile"));JSONObject customer=customer(s,phone,false);long reward=0;
  if(redeem>0){if(!settings.getBoolean("loyalty"))throw new Exception("Loyalty is disabled.");if(customer==null||customer.getLong("points")<settings.getLong("minimumPoints"))throw new Exception("Customer needs at least "+settings.getLong("minimumPoints")+" points before redemption.");if(redeem>customer.getLong("points"))throw new Exception("Not enough points.");reward=Math.multiplyExact(redeem,settings.getLong("pointValue"));}
  long total=subtotal-discount-reward;if(total<=0)throw new Exception("Discount/points must leave a positive bill amount.");long tax=BigDecimal.valueOf(total).multiply(BigDecimal.valueOf(settings.getDouble("taxRate"))).divide(BigDecimal.valueOf(100).add(BigDecimal.valueOf(settings.getDouble("taxRate"))),0,RoundingMode.HALF_UP).longValueExact();
  long earned=phone.isEmpty()||!settings.getBoolean("loyalty")?0:total/settings.getLong("earnSpend");return obj("lines",lines,"subtotal",subtotal,"discount",discount,"reward",reward,"total",total,"tax",tax,"cost",cost,"mobile",phone,"redeem",redeem,"earned",earned);
 }
 public static JSONObject act(JSONObject s,String action,JSONObject a,String uid)throws Exception{
  if(action.equals("setup")){if(s.getJSONArray("users").length()>0)throw new Exception("Owner already exists.");JSONObject u=createUser(s,a);s.getJSONObject("settings").put("name",text(a,"shop",100,true));audit(s,u.getString("id"),"Owner created");return obj("uid",u.getString("id"));}
  JSONObject u=user(s,uid);JSONObject result=obj("ok",true);
  if(action.equals("user")){admin(u);JSONObject newUser=createUser(s,a);audit(s,uid,"Created user "+newUser.getString("name"));}
  else if(action.equals("toggleUser")){admin(u);JSONObject target=find(s.getJSONArray("users"),a.getString("id"));if(target.getString("id").equals(uid))throw new Exception("You cannot disable your own account.");target.put("active",!target.getBoolean("active"));audit(s,uid,"Changed user access: "+target.getString("name"));}
  else if(action.equals("product")){admin(u);String pid=a.optString("id"),sku=text(a,"sku",40,true);JSONArray ps=s.getJSONArray("products");for(int i=0;i<ps.length();i++)if(ps.getJSONObject(i).getString("sku").equalsIgnoreCase(sku)&&!ps.getJSONObject(i).getString("id").equals(pid))throw new Exception("Product code already exists.");boolean fresh=pid.isEmpty();JSONObject p=fresh?obj("id",id(),"stock",0):find(ps,pid);long price=bounded(a,"price",100000000),cost=bounded(a,"cost",100000000);if(price==0)throw new Exception("Selling price must be greater than zero.");p.put("sku",sku).put("name",text(a,"name",120,true)).put("size",text(a,"size",30,false)).put("colour",text(a,"colour",40,false)).put("price",price).put("cost",fresh?cost:p.getLong("cost")).put("active",a.optBoolean("active",true)).put("alert",bounded(a,"alert",100000));if(fresh){ps.put(p);long qty=bounded(a,"qty",100000);p.put("stock",qty);if(qty>0)movement(s,p,qty,cost,"Opening",uid,"Opening stock","");}audit(s,uid,"Saved product "+sku);}
  else if(action.equals("stock")){admin(u);JSONObject p=find(s.getJSONArray("products"),a.getString("id"));String type=a.getString("type");long qty=bounded(a,"qty",100000);if(qty==0)throw new Exception("Enter quantity.");String note=text(a,"note",200,true);long unit=p.getLong("cost");if(type.equals("Purchase")){unit=bounded(a,"cost",100000000);long old=p.getLong("stock"),newStock=Math.addExact(old,qty);long newCost=BigDecimal.valueOf(old).multiply(BigDecimal.valueOf(p.getLong("cost"))).add(BigDecimal.valueOf(qty).multiply(BigDecimal.valueOf(unit))).divide(BigDecimal.valueOf(newStock),0,RoundingMode.HALF_UP).longValueExact();p.put("cost",newCost);p.put("stock",newStock);}else if(type.equals("Wastage")){if(qty>p.getLong("stock"))throw new Exception("Stock cannot be negative.");p.put("stock",p.getLong("stock")-qty);qty=-qty;}else throw new Exception("Invalid stock action.");movement(s,p,qty,unit,type,uid,note,"");audit(s,uid,"Stock "+type+" "+p.getString("sku"));}
  else if(action.equals("opening")){long amount=bounded(a,"amount",1000000000);JSONArray os=s.getJSONArray("openings");for(int i=0;i<os.length();i++)if(os.getJSONObject(i).getString("day").equals(today())&&os.getJSONObject(i).getString("user").equals(uid))throw new Exception("Opening balance is already recorded for today.");os.put(obj("id",id(),"day",today(),"user",uid,"amount",amount));audit(s,uid,"Opening balance recorded");}
  else if(action.equals("expense")){admin(u);long amount=bounded(a,"amount",1000000000);if(amount==0)throw new Exception("Expense must be positive.");String method=a.getString("method");if(!Arrays.asList("Cash","UPI","Card").contains(method))throw new Exception("Invalid payment method.");s.getJSONArray("expenses").put(obj("id",id(),"day",today(),"time",now(),"user",uid,"amount",amount,"method",method,"note",text(a,"note",200,true)));audit(s,uid,"Expense recorded");}
  else if(action.equals("settings")){admin(u);JSONObject st=s.getJSONObject("settings");st.put("name",text(a,"name",100,true)).put("address",text(a,"address",300,false)).put("phone",text(a,"phone",30,false)).put("gstin",text(a,"gstin",25,false)).put("footer",text(a,"footer",150,false));long spend=bounded(a,"earnSpend",100000000),value=bounded(a,"pointValue",100000),min=bounded(a,"minimumPoints",1000000);if(spend==0||value==0||min==0)throw new Exception("Loyalty values must be positive.");double tax=a.getDouble("taxRate");if(tax<0||tax>40||!Double.isFinite(tax))throw new Exception("Tax rate: 0–40%.");st.put("earnSpend",spend).put("pointValue",value).put("minimumPoints",min).put("loyalty",a.getBoolean("loyalty")).put("taxRate",tax);audit(s,uid,"Store settings updated");}
  else if(action.equals("logo")){admin(u);String logo=a.getString("logo");if(logo.length()>600000)throw new Exception("Logo is too large.");s.getJSONObject("settings").put("logo",logo);audit(s,uid,"Shop logo updated");}
  else if(action.equals("checkout")){
   String key=text(a,"key",80,true);JSONArray bs=s.getJSONArray("bills");for(int i=0;i<bs.length();i++)if(bs.getJSONObject(i).getString("key").equals(key)){JSONObject previous=bs.getJSONObject(i);if(!previous.getString("user").equals(uid))throw new Exception("Payment belongs to another cashier.");return obj("bill",previous);}
   JSONObject b=quote(s,a);long cashReceived=bounded(a,"received",1000000000),upi=bounded(a,"upi",1000000000),card=bounded(a,"card",1000000000),total=b.getLong("total");if(upi+card>total)throw new Exception("UPI + Card exceeds the bill total.");long cash=total-upi-card;if(cashReceived<cash||(cash==0&&cashReceived>0))throw new Exception("Check cash received.");String phone=b.getString("mobile");JSONObject c=customer(s,phone,true);if(c!=null){String name=text(a,"customerName",100,false);if(!name.isEmpty())c.put("name",name);c.put("points",Math.addExact(c.getLong("points")-b.getLong("redeem"),b.getLong("earned")));b.put("customerName",c.getString("name"));}else b.put("customerName","");
   long num=s.getLong("nextBill");s.put("nextBill",num+1);b.put("id",id()).put("number",num).put("key",key).put("time",now()).put("day",today()).put("user",uid).put("cashier",u.getString("name")).put("cash",cash).put("upi",upi).put("card",card).put("received",cashReceived).put("change",cashReceived-cash).put("shop",new JSONObject(s.getJSONObject("settings").toString()));
   JSONArray ls=b.getJSONArray("lines");for(int i=0;i<ls.length();i++){JSONObject l=ls.getJSONObject(i),p=find(s.getJSONArray("products"),l.getString("id"));p.put("stock",p.getLong("stock")-l.getLong("qty"));movement(s,p,-l.getLong("qty"),l.getLong("cost"),"Sale",uid,"",b.getString("id"));}if(c!=null)s.getJSONArray("points").put(obj("mobile",phone,"day",today(),"bill",num,"earned",b.getLong("earned"),"used",b.getLong("redeem"),"balance",c.getLong("points")));bs.put(b);audit(s,uid,"Paid bill C-"+num);result=obj("bill",b);
  }else throw new Exception("Unknown action.");
  return result;
 }
 static void movement(JSONObject s,JSONObject p,long qty,long cost,String type,String user,String note,String bill)throws Exception{s.getJSONArray("movements").put(obj("id",id(),"day",today(),"time",now(),"product",p.getString("id"),"sku",p.getString("sku"),"name",p.getString("name"),"qty",qty,"cost",cost,"value",Math.multiplyExact(qty,cost),"type",type,"user",user,"note",note,"bill",bill));}
 public static JSONObject safe(JSONObject s,String uid)throws Exception{JSONObject copy=new JSONObject(s.toString());JSONArray users=copy.getJSONArray("users");for(int i=0;i<users.length();i++){users.getJSONObject(i).remove("hash");users.getJSONObject(i).remove("salt");}copy.put("today",today());if(uid==null||uid.isEmpty())return obj("setup",users.length()==0);JSONObject u=user(s,uid);
  JSONObject me=new JSONObject(u.toString());me.remove("hash");me.remove("salt");copy.put("me",me);
  if(!u.getBoolean("admin")){for(String key:new String[]{"bills","openings","expenses"}){JSONArray filtered=new JSONArray(),all=copy.getJSONArray(key);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optString("user").equals(uid))filtered.put(all.getJSONObject(i));copy.put(key,filtered);}copy.put("movements",new JSONArray()).put("audit",new JSONArray()).put("points",new JSONArray());for(int i=0;i<copy.getJSONArray("products").length();i++)copy.getJSONArray("products").getJSONObject(i).put("cost",0);}
  return copy;
 }
 public static void validateBackup(JSONObject s)throws Exception{
  if(s.getInt("schema")!=1)throw new Exception("This backup version is not supported.");
  for(String k:new String[]{"users","products","bills","customers","movements","points","openings","expenses","audit"})if(s.getJSONArray(k).length()>200000)throw new Exception("Backup exceeds supported size.");
  for(String table:new String[]{"users","products","bills","movements","openings","expenses"}){Set<String> keys=new HashSet<>();JSONArray arr=s.getJSONArray(table);for(int i=0;i<arr.length();i++){String key=arr.getJSONObject(i).getString("id");if(!key.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}")||!keys.add(key))throw new Exception("Invalid record ID.");}}
  Set<String> ids=new HashSet<>(),mobiles=new HashSet<>();boolean owner=false;JSONArray us=s.getJSONArray("users");for(int i=0;i<us.length();i++){JSONObject u=us.getJSONObject(i);if(!ids.add(u.getString("id"))||!u.getString("hash").matches("[0-9a-f]{64}")||!u.getString("salt").matches("[0-9a-f]{48}"))throw new Exception("Invalid user data.");owner|=u.getBoolean("active")&&u.getBoolean("admin");}if(!owner)throw new Exception("Backup needs an active administrator.");
  Map<String,Long> stock=new HashMap<>();JSONArray ms=s.getJSONArray("movements");for(int i=0;i<ms.length();i++){JSONObject m=ms.getJSONObject(i);String id=m.getString("product");stock.put(id,Math.addExact(stock.containsKey(id)?stock.get(id):0,m.getLong("qty")));}
  JSONArray ps=s.getJSONArray("products");Set<String> codes=new HashSet<>();for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);if(p.getLong("price")<=0||p.getLong("cost")<0||p.getLong("stock")<0||!codes.add(p.getString("sku").toLowerCase(Locale.ROOT))||p.getLong("stock")!=(stock.containsKey(p.getString("id"))?stock.get(p.getString("id")):0))throw new Exception("Invalid product/stock data.");}
  JSONArray cs=s.getJSONArray("customers");for(int i=0;i<cs.length();i++){JSONObject c=cs.getJSONObject(i);if(!c.getString("mobile").matches("[0-9]{10}")||!mobiles.add(c.getString("mobile"))||c.getLong("points")<0)throw new Exception("Invalid customer points.");}
  long max=0;Set<Long> numbers=new HashSet<>();JSONArray bs=s.getJSONArray("bills");for(int i=0;i<bs.length();i++){JSONObject b=bs.getJSONObject(i);long num=b.getLong("number"),total=b.getLong("total");max=Math.max(max,num);if(num<1||!numbers.add(num)||total<=0||total!=b.getLong("subtotal")-b.getLong("discount")-b.getLong("reward")||total!=b.getLong("cash")+b.getLong("upi")+b.getLong("card"))throw new Exception("Invalid invoice data.");}if(s.getLong("nextBill")<=max)throw new Exception("Invalid invoice sequence.");JSONObject st=s.getJSONObject("settings");if(st.getLong("earnSpend")<=0||st.getLong("pointValue")<=0||st.getLong("minimumPoints")<1||st.getDouble("taxRate")<0||st.getDouble("taxRate")>40)throw new Exception("Invalid store settings.");
 }

}
